type OrderEvent =
  | Create(id: String)
  | Pay(id: String)
  | Ship(id: String)
  | Cancel(id: String)

fn verb_of(e: OrderEvent) -> (String, String) {
  return match e {
    Create(id) => ("create", id),
    Pay(id) => ("pay", id),
    Ship(id) => ("ship", id),
    Cancel(id) => ("cancel", id),
  }
}

fn allowed(verb: String, state: String) -> Bool {
  let pay = verb == "pay" && state == "created"
  let ship = verb == "ship" && state == "paid"
  let cancel = verb == "cancel" && (state == "created" || state == "paid")
  return pay || ship || cancel
}

fn target(verb: String) -> String {
  return match verb {
    "pay" => "paid",
    "ship" => "shipped",
    _ => "cancelled",
  }
}

