def session_totals(events: list[Session]) -> list[tuple[str, int]]:
    """Total logged-in time per user, sorted by user name."""
    totals: dict[str, int] = {}
    open_since: dict[str, int] = {}
    for event in events:
        user, time = event["user"], event["time"]
        totals.setdefault(user, 0)
        if event["kind"] == "login":
