import time
import urllib.error
import urllib.request


def classify(latency_ms: int) -> str:
    """Health class for a probe latency (-1 means the probe failed)."""
    if latency_ms < 0:
        return "down"
    elif latency_ms <= 1000:
        return "healthy"
    return "degraded"


